insert into courses (id,title,category_id,level,level_label,description,prerequisites,accreditation,certificate_label,unit_count,total_hours,publication_status,version) values (
  'nc-motor-vehicle-repairs-level-2', 'Motor Vehicle Repairs — Level 2', 'automotive', 2, 'Intermediate', 'This Level 2 programme develops the practical skills and knowledge needed to service and repair motor vehicles in an automotive workplace. Trainees learn safe working practices and the use of tools and equipment; inspect and service braking, steering, suspension, cooling, transmission and electrical systems; disassemble and reassemble engines, cylinder heads and sub-assemblies; and apply manufacturer repair procedures and basic troubleshooting. The programme also builds supporting workplace competencies in communication, customer service, computer applications and record keeping.', 'No formal prerequisite; a basic command of English and numeracy is recommended.', 'UNVERIFIED', 'CHCN L2', 36, 2625, 'published', 1)
