insert into courses (id,title,category_id,level,level_label,description,prerequisites,accreditation,certificate_label,unit_count,total_hours,publication_status,version) values (
  'nc-massage-therapy-level-4', 'Massage Therapy — Level 4', 'beauty-wellness', 4, 'Advanced', 'This Massage Therapy course is a profession in which the practitioner applies manual techniques, and may apply adjunctive therapies, with the intention of positively affecting the health and well-being of the client. Therapeutic massage involves the manipulation of the soft tissue structures of the body to prevent and alleviate pain, discomfort, muscle spasm, and stress; and to promote health and wellness. Massage therapy improves functioning of the circulatory, lymphatic, muscular, skeletal, and nervous systems and may improve the rate at which the body recovers from injury and illness.', 'Prior industry experience and completion of the relevant lower-level competencies are recommended; no formal platform prerequisite is enforced.', 'UNVERIFIED', 'CHCN L4', 45, 1431, 'published', 1)
