insert into courses (id,title,category_id,level,level_label,description,prerequisites,accreditation,certificate_label,unit_count,total_hours,publication_status,version) values (
  'nc-business-management-supervision-level-3', 'Business Management — (Supervision) — Level 3', 'business-management', 3, 'Advanced', 'This programme is designed to comprehensively cover the major aspects of business, management and supervision necessary to advance and succeed in business and industry. The course work covers basic business management skills, with emphasis on human relations, leadership, and written and oral communication specifically related to managerial and supervisory positions. It is designed to meet the needs of those who plan to (1) prepare for supervisory positions, (2) advance from existing supervisory or management roles to more responsible positions, and (3) own and operate their own business.', 'Prior experience in the field or completion of the Level 2 competencies is recommended; no formal platform prerequisite is enforced.', 'UNVERIFIED', 'CHCN L3', 64, 1562, 'published', 1)
on conflict (id) do update set title=excluded.title, description=excluded.description,
  unit_count=excluded.unit_count, total_hours=excluded.total_hours, updated_at=now();

