insert into courses (id,title,category_id,level,level_label,description,prerequisites,accreditation,certificate_label,unit_count,total_hours,publication_status,version) values (
  'nc-supervisory-management-level-3', 'Supervisory Management — Level 3', 'business-management', 3, 'Advanced', 'Supervisory Management Skills provides you with the necessary knowledge and insights to become successful in any supervisory position by focusing on and improving important managerial skills. As manager or supervisor, you often have to manage various operational aspects as well as the people side of business simultaneously, which can lead to situations of great stress or anxiety. During the course, you will acquire the requisite skills to make sound (yet creative) decisions, develop techniques to communicate better, manage and organise your time optimally, manage staff and conflict situations, improve productivity and implement total quality control measures', 'Prior experience in the field or completion of the Level 2 competencies is recommended; no formal platform prerequisite is enforced.', 'UNVERIFIED', 'CHCN L3', 50, 3855, 'published', 1)
