insert into courses (id,title,category_id,level,level_label,description,prerequisites,accreditation,certificate_label,unit_count,total_hours,publication_status,version) values (
  'nc-electrical-installation-level-3', 'Electrical Installation — Level 3', 'electrical-hvac', 3, 'Advanced', 'This Level 3 Diploma in Electrical Installation aims to provide learners with more complex competencies to expand their skillset and to supervise and operate a business venture effectively. Learners will cover cluster/modules that will expose them to the coordination and installation of detailed residential, commercial and industrial wiring; industrial machines, components and systems to include motor controls. Emphasis is placed on wiring in accordance with the provisions contained in the Jamaica Standards 316 and other relevant codes. ', 'Prior experience in the field or completion of the Level 2 competencies is recommended; no formal platform prerequisite is enforced.', 'UNVERIFIED', 'CHCN L3', 63, 4340, 'published', 1)
