insert into courses (id,title,category_id,level,level_label,description,prerequisites,accreditation,certificate_label,unit_count,total_hours,publication_status,version) values (
  'nc-mechatronics-level-3', 'Mechatronics — Level 3', 'electrical-hvac', 3, 'Advanced', 'This course is an emerging field that blends mechanical engineering, electrical engineering and computer science to design, build and operate smart machines. This programme gives the trainees a broad range of knowledge and skills in manufacturing processes, industrial control principles, including instruments, circuits, components and control techniques. Statistics that include mechatronic control systems and programmable logic controllers, practical physics, including dynamics and fluid power. The physical and chemical properties of materials used in industry, machine design elements and kinematics, process control in plant automation and computer-integrated manufacturing.', 'Prior experience in the field or completion of the Level 2 competencies is recommended; no formal platform prerequisite is enforced.', 'UNVERIFIED', 'CHCN L3', 54, 3705, 'published', 1)
