insert into courses (id,title,category_id,level,level_label,description,prerequisites,accreditation,certificate_label,unit_count,total_hours,publication_status,version) values (
  'nc-housekeeping-supervison-level-3', 'Housekeeping Supervision — Level 3', 'business-management', 3, 'Advanced', 'The Housekeeping Supervision programme is designed to equip learners with the knowledge, skills, and competencies required to supervise housekeeping operations effectively within hotels, resorts, guesthouses, and other accommodation establishments. The programme focuses on room and public-area cleaning standards, staff supervision, work scheduling, quality control, inventory management, health and safety, and guest service. Learners will develop practical skills in coordinating housekeeping teams, inspecting rooms and facilities, maintaining cleanliness standards, controlling supplies and equipment, addressing guest concerns, and ensuring compliance with workplace procedures. Emphasis is placed on leadership, communication, teamwork, professionalism, efficiency, and attention to detail.', 'Prior experience in the field or completion of the Level 2 competencies is recommended; no formal platform prerequisite is enforced.', 'UNVERIFIED', 'CHCN L3', 60, 3800, 'published', 1)
on conflict (id) do update set title=excluded.title, description=excluded.description,
