insert into courses (id,title,category_id,level,level_label,description,prerequisites,accreditation,certificate_label,unit_count,total_hours,publication_status,version) values (
  'nc-data-operations-level-2', 'Data Operations — Level 2', 'ict', 2, 'Intermediate', 'This Level 2 programme equips trainees with the practical skills to work effectively in an information-technology environment and perform data operations. It covers operating a personal computer and word-processing, spreadsheet, database and presentation applications; data entry and internet use; SQL for creating database structures and manipulating data; multimedia production with text, images and graphics; connecting and maintaining hardware and software; and communicating professionally with clients, all underpinned by occupational health and safety and teamwork.', 'No formal prerequisite; a basic command of English and numeracy is recommended.', 'UNVERIFIED', 'CHCN L2', 37, 690, 'published', 1)
